using GastricCancerDetection.Application.Interfaces; using Microsoft.AspNetCore.Mvc;
namespace GastricCancerDetection.Api.Controllers; [ApiController][Route("api/reports")] public class AdvancedReportsController:ControllerBase { private readonly IReportService _reports; public AdvancedReportsController(IReportService reports)=>_reports=reports; [HttpPost("generate/{runId:int}")] public async Task<IActionResult> Generate(int runId,[FromQuery]string format="Excel",CancellationToken ct=default){var path=string.Equals(format,"PDF",StringComparison.OrdinalIgnoreCase)?await _reports.GeneratePdfAsync(runId,ct):await _reports.GenerateExcelAsync(runId,ct);return Ok(new {runId,format,path});} }
